.ds{--p-bg:#ffffff;--p-surface:#f1f3f6;--p-high:#fafbfc;--p-hover:#e1e6ed;--p-row-active:#e5e9f2;--p-disabled:#dce1e8;--p-glass:#f6f8fbe8;--p-backdrop:#2c333d66;--p-tile:#f2f3f0;--p-tile-header:#f3f4f1;--p-image-well:#e7e9e4;--p-selected-surface:#e7f0eb;--p-ink:#2c333d;--p-muted:#59636f;--p-on-accent:#ffffff;--p-line:#c2cad5;--p-line-subtle:#cbd2dc;--p-control-border:#7b8592;--p-edge:#ffffff;--p-edge-soft:#ffffffa8;--p-accent:#303b48;--p-accent-hover:#25303d;--p-shade:#000;--p-highlight:#6153b5;--p-highlight-soft:#e2ddf3;--p-soft:#d3e8de;--p-mark:#ffbf63;--p-mark-hover:#ffd07b;--p-mark-alt:#9ad9aa;--p-error:#a3313e;--p-error-soft:#f9e8e9;--p-error-line:#d4a2a8;--p-success:#26614f;--p-success-soft:#e5f2eb;--p-success-line:#8fb8a5;--p-warning:#805719;--p-warning-soft:#f6efd9;--p-warning-line:#b9a16f;--p-font:Pretendard, sans-serif;--p-display-font:Outfit, Pretendard, sans-serif;--p-text-sm:13px;--p-text-md:16px;--p-text-lg:24px;--p-space-xs:8px;--p-space-sm:12px;--p-space-md:16px;--p-space-lg:24px;--p-space-xl:32px;--p-radius:24px;--p-control-radius:16px;--p-inner-radius:12px;--p-shadow:6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed;--p-raised:3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed;--p-inset:inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9;--p-pressed:inset 3px 3px 6px #15222f60,inset -1px -1px 3px #ffffff18;--p-float:0 12px 32px #26394d26;--p-lift:0 3px 5px #24314526;--p-control-shadow:0 3px 5px #24314526,inset 0 1px 0 #ffffff24;--p-selected-shadow:0 2px 5px #24314526;--p-knob-shadow:0 1px 3px #26344726;--p-glass-shadow:0 8px 24px #38465e12;--p-dialog-shadow:0 24px 80px #26344740;--p-drop:0 10px 12px #24293616;--p-ring:inset 0 0 0 2px #24293610;--p-focus-glow:0 0 0 2px #ed667b33;}
.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-text-md)/1.5 var(--p-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--p-highlight); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:20px; color:var(--p-muted); }
.ds .ds-surface { border:1px solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-tablist { display:flex; padding:5px; border:1px solid var(--p-line); border-radius:20px; gap:4px; background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-tab { flex:1; min-width:44px; min-height:44px; padding:10px 12px; border:1px solid transparent; border-radius:14px; background:transparent; font-size:14px; color:var(--p-muted); font-weight:550; }
.ds .ds-tab:hover { background:var(--p-surface); }
.ds .ds-tab[aria-selected="true"] { background:var(--p-accent); color:var(--p-on-accent); font-weight:650; box-shadow:var(--p-selected-shadow); }
.ds .ds-tabpanel { padding:var(--p-space-lg) 4px; font-size:14px; }
/* Looks: one tab markup, eight shapes. The chosen tab always gains a mark or a shape change, never only a color. */
.ds .ds-tabs[data-look] .ds-tab { display:inline-flex; justify-content:center; align-items:center; gap:6px; }
.ds .ds-tabs[data-look] .ds-tab .ui-icon { width:22px; height:22px; }
/* 02 underline: bare row on a hairline, a thick bar under the chosen tab */
.ds .ds-tabs[data-look="underline"] .ds-tablist { padding:0; gap:0; border:0; border-bottom:1px solid var(--p-line); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="underline"] .ds-tab { border-radius:0; }
.ds .ds-tabs[data-look="underline"] .ds-tab[aria-selected="true"] { background:transparent; color:var(--p-ink); box-shadow:inset 0 -3px 0 var(--p-accent); }
/* 03 segmented: gray track, the chosen segment rises as a white tile */
.ds .ds-tabs[data-look="segmented"] .ds-tablist { padding:4px; border:0; border-radius:12px; background:var(--p-surface); box-shadow:none; }
.ds .ds-tabs[data-look="segmented"] .ds-tab { border-radius:9px; }
.ds .ds-tabs[data-look="segmented"] .ds-tab[aria-selected="true"] { background:var(--p-high); color:var(--p-ink); border-color:var(--p-line); box-shadow:var(--p-raised); }
/* 04 outline: separate boxes, the chosen one gets a double-weight edge */
.ds .ds-tabs[data-look="outline"] .ds-tablist { padding:0; gap:8px; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="outline"] .ds-tab { border-color:var(--p-control-border); border-radius:var(--p-control-radius); background:var(--p-high); }
.ds .ds-tabs[data-look="outline"] .ds-tab[aria-selected="true"] { background:var(--p-high); color:var(--p-ink); border-color:var(--p-ink); box-shadow:inset 0 0 0 1px var(--p-ink); }
/* 05 float: loose pills, the chosen one filled soft and ringed */
.ds .ds-tabs[data-look="float"] .ds-tablist { padding:0; gap:8px; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="float"] .ds-tab { flex:none; padding-inline:18px; border-radius:999px; }
.ds .ds-tabs[data-look="float"] .ds-tab[aria-selected="true"] { background:var(--p-soft); color:var(--p-ink); box-shadow:inset 0 0 0 1.5px var(--p-ink); }
/* 06 icon: picture over the name, a soft capsule behind the chosen picture */
.ds .ds-tabs[data-look="icon"] .ds-tablist { padding:0; border:0; border-bottom:1px solid var(--p-line); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="icon"] .ds-tab { flex-direction:column; gap:4px; min-height:64px; padding:8px; border-radius:0; font-size:12px; }
.ds .ds-tabs[data-look="icon"] .ds-tab .ui-icon { box-sizing:content-box; padding:4px 16px; border-radius:999px; }
.ds .ds-tabs[data-look="icon"] .ds-tab[aria-selected="true"] { background:transparent; color:var(--p-ink); box-shadow:none; }
.ds .ds-tabs[data-look="icon"] .ds-tab[aria-selected="true"] .ui-icon { background:var(--p-soft); stroke-width:2.2; }
/* 07 vertical: list on the left, a side bar on the chosen row; arrows go up and down */
.ds .ds-tabs[data-look="vertical"] { display:grid; grid-template-columns:minmax(96px,auto) minmax(0,1fr); align-items:start; }
.ds .ds-tabs[data-look="vertical"] .ds-tablist { flex-direction:column; padding:0 8px 0 0; gap:2px; border:0; border-right:1px solid var(--p-line); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="vertical"] .ds-tab { justify-content:flex-start; border-radius:10px 0 0 10px; }
.ds .ds-tabs[data-look="vertical"] .ds-tab[aria-selected="true"] { background:var(--p-surface); color:var(--p-ink); box-shadow:inset 3px 0 0 var(--p-accent); }
.ds .ds-tabs[data-look="vertical"] .ds-tabpanel { padding:12px 16px; }
/* 08 folder: file-folder tabs, the chosen one joins the panel below */
.ds .ds-tabs[data-look="folder"] .ds-tablist { position:relative; z-index:1; padding:0 8px; gap:4px; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="folder"] .ds-tab { margin-bottom:-1px; border-color:var(--p-line); border-radius:12px 12px 0 0; background:var(--p-surface); }
.ds .ds-tabs[data-look="folder"] .ds-tab[aria-selected="true"] { background:var(--p-high); color:var(--p-ink); border-bottom-color:var(--p-high); box-shadow:none; }
.ds .ds-tabs[data-look="folder"] .ds-tabpanel { padding:16px; border:1px solid var(--p-line); border-radius:0 0 var(--p-control-radius) var(--p-control-radius); background:var(--p-high); }

'use client';
import React, { useId, useState } from 'react';
const defaults = [{ value: 'all', label: '전체', content: '모든 컬렉션을 보고 있어요.' }, { value: 'progress', label: '진행 중', content: '진행 중인 컬렉션을 보고 있어요.' }, { value: 'done', label: '완료', content: '완료한 컬렉션을 보고 있어요.' }];
// look matches the HTML data-look values; the vertical look stacks the tabs and moves with the up and down arrows.
export function Tabs({ items = defaults, value, defaultValue, onValueChange, label = '컬렉션 분류', look = 'filled' }) {
  const id = useId(); const [local, setLocal] = useState(defaultValue ?? items[0]?.value);
  const chosen = value ?? local;
  const active = items.some(item => item.value === chosen) ? chosen : items[0]?.value;
  const vertical = look === 'vertical';
  const [back, forward] = vertical ? ['ArrowUp', 'ArrowDown'] : ['ArrowLeft', 'ArrowRight'];
  function select(next) { setLocal(next); onValueChange?.(next); }
  function keydown(event, index) {
    if (![back, forward, 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : (index + (event.key === forward ? 1 : -1) + items.length) % items.length;
    event.currentTarget.parentElement.children[next].focus(); select(items[next].value);
  }
  return <div className="ds-tabs" data-look={look}><div role="tablist" className="ds-tablist" aria-label={label} aria-orientation={vertical ? 'vertical' : undefined}>{items.map((item, i) => <button type="button" key={item.value} id={`${id}-tab-${i}`} className="ds-tab" role="tab" aria-selected={active === item.value} aria-controls={`${id}-panel-${i}`} tabIndex={active === item.value ? 0 : -1} onClick={() => select(item.value)} onKeyDown={event => keydown(event, i)}>{item.icon}{item.label}</button>)}</div>{items.map((item, i) => <div key={item.value} id={`${id}-panel-${i}`} className="ds-tabpanel" role="tabpanel" aria-labelledby={`${id}-tab-${i}`} hidden={active !== item.value} tabIndex={0}>{item.content}</div>)}</div>;
}

